//! B0 (AF.12) job artifacts in `mode=services`: the `make` action declares
//! sessionless artifacts owned by its own invocation, answers once every
//! `ARTIFACT_DECLARED` arrived, and opens each one as its opaque key says.
//!
//! `make` takes `{"declare": [{"name", "size", "source", "path"?}]}`. Each
//! entry is declared with the entry itself as its key. `source = "stream"`
//! opens a fresh request-owned stream lease of the generated bytes
//! ([`crate::services::generated`]); `source = "file"` names `path` below
//! the plugin-wide `artifacts` root, the control's `root`, declared with no
//! session on the first `make`. The result is `{"declared": [...]}`: each
//! artifact id, or the refusal's code.
//!
//! Receipts: `make` (with the root declaration's status), `declared`,
//! `open`, `artifact_read`, `artifact_close` and `release`, so a test reads
//! from the child's own journal that every lease closed before its
//! artifact's `ARTIFACT_RELEASE`.

use std::collections::HashMap;

use vosu_plugin_api::{
    ActionInvoke, ActionStatus, ArtifactDeclare, ArtifactDeclared, CborBytes, CborValue,
    HostServices, Message, PluginError, ResourceResolved, StreamChunk, VOSU_STREAM_CHUNK_MAX_BYTES,
    VtableHostServices, vosu_status,
};

use crate::control::Control;
use crate::services::{finish, generated, integer, map, not_found, reply_to, show, text, value};

/// Artifact stream ids start here, apart from the resource leases.
const FIRST_STREAM: u64 = 1 << 40;

/// One `make` invocation waiting for its declarations' replies.
struct Waiting {
    remaining: usize,
    declared: Vec<CborValue>,
}

pub struct Artifacts {
    control: &'static Control,
    root_declared: bool,
    next_correlation: u64,
    /// Declaration correlation → (invocation, index).
    pending: HashMap<u64, (u64, usize)>,
    waiting: HashMap<u64, Waiting>,
    /// Live stream lease → where its bytes end.
    streams: HashMap<u64, u64>,
    next_stream: u64,
}

impl Artifacts {
    pub fn new(control: &'static Control) -> Self {
        Self {
            control,
            root_declared: false,
            next_correlation: 0,
            pending: HashMap::new(),
            waiting: HashMap::new(),
            streams: HashMap::new(),
            next_stream: FIRST_STREAM,
        }
    }

    /// The `make` action.
    pub fn make(&mut self, host: &VtableHostServices, invoke: ActionInvoke) {
        let root = match (&self.control.root, self.root_declared) {
            (Some(root), false) => {
                self.root_declared = true;
                host.declare_root(None, "artifacts", root) as u32
            }
            _ => 0,
        };
        let specs = match value(&invoke.args, "declare") {
            Some(CborValue::Array(specs)) => specs,
            _ => Vec::new(),
        };
        self.control.receipt(
            "make",
            &format!(
                "invocation={} caller_kind={:?} count={} root={root}",
                invoke.invocation,
                invoke.caller.kind,
                specs.len()
            ),
        );
        if specs.is_empty() {
            self.answer(host, invoke.invocation, Vec::new());
            return;
        }
        self.waiting.insert(
            invoke.invocation,
            Waiting {
                remaining: specs.len(),
                declared: vec![CborValue::Null; specs.len()],
            },
        );
        for (index, spec) in specs.into_iter().enumerate() {
            self.next_correlation += 1;
            self.pending
                .insert(self.next_correlation, (invoke.invocation, index));
            let declare = ArtifactDeclare {
                invocation: invoke.invocation,
                name: text(&spec, "name").unwrap_or_default(),
                content_id: CborValue::Text(format!("b0-{}-{index}", invoke.invocation)),
                size: integer(&spec, "size").unwrap_or(0) as u64,
                key: spec,
            };
            let status = host.send(&Message::ArtifactDeclare(declare), self.next_correlation);
            if status != vosu_status::VOSU_OK {
                self.control
                    .receipt("declare_refused", &format!("status={}", status as u32));
            }
        }
    }

    /// Handles the artifact messages and this module's stream leases;
    /// every other message is handed back.
    pub fn dispatch(
        &mut self,
        host: &VtableHostServices,
        message: Message,
        correlation: u64,
    ) -> Result<Option<Message>, PluginError> {
        match message {
            Message::ArtifactDeclared(reply) => {
                let Some((invocation, index)) = self.pending.remove(&correlation) else {
                    return Err(vosu_status::VOSU_ERR_INVALID_ARGUMENT.into());
                };
                let declared = match reply {
                    ArtifactDeclared::Artifact { artifact } => CborValue::Text(artifact),
                    ArtifactDeclared::Error { error } => {
                        map(&[("error", CborValue::Text(error.code))])
                    }
                };
                self.control.receipt(
                    "declared",
                    &format!(
                        "invocation={invocation} index={index} reply={}",
                        show(&declared)
                    ),
                );
                let waiting = self
                    .waiting
                    .get_mut(&invocation)
                    .ok_or(PluginError(vosu_status::VOSU_ERR_INVALID_ARGUMENT))?;
                waiting.declared[index] = declared;
                waiting.remaining -= 1;
                if waiting.remaining == 0
                    && let Some(waiting) = self.waiting.remove(&invocation)
                {
                    self.answer(host, invocation, waiting.declared);
                }
            }
            Message::ArtifactOpen(open) => {
                let size = integer(&open.key, "size").unwrap_or(0) as u64;
                let (reply, stream) = match text(&open.key, "source").as_deref() {
                    Some("stream") => {
                        self.next_stream += 1;
                        self.streams.insert(self.next_stream, size);
                        (
                            ResourceResolved::Stream {
                                stream: self.next_stream,
                                size,
                            },
                            self.next_stream,
                        )
                    }
                    Some("file") => (
                        ResourceResolved::Path {
                            root: "artifacts".into(),
                            path: text(&open.key, "path").unwrap_or_default(),
                        },
                        0,
                    ),
                    _ => (not_found(), 0),
                };
                self.control.receipt(
                    "open",
                    &format!("artifact={} stream={stream}", open.artifact),
                );
                reply_to(host, reply, correlation)?;
            }
            Message::ArtifactRelease(release) => {
                self.control.receipt(
                    "release",
                    &format!("artifact={} key={}", release.artifact, show(&release.key)),
                );
            }
            Message::StreamRead(read) if self.streams.contains_key(&read.stream) => {
                self.control.receipt(
                    "artifact_read",
                    &format!(
                        "stream={} offset={} len={}",
                        read.stream, read.offset, read.len
                    ),
                );
                if read.len > VOSU_STREAM_CHUNK_MAX_BYTES {
                    return Err(vosu_status::VOSU_ERR_INVALID_ARGUMENT.into());
                }
                let end = read
                    .offset
                    .saturating_add(u64::from(read.len))
                    .min(self.streams[&read.stream]);
                let data = (read.offset.min(end)..end).map(generated).collect();
                // A read core already abandoned is refused; the close follows.
                let _ = host.send(
                    &Message::StreamChunk(StreamChunk::Data {
                        data: CborBytes(data),
                    }),
                    correlation,
                );
            }
            Message::StreamClose(close) if self.streams.contains_key(&close.stream) => {
                self.streams.remove(&close.stream);
                self.control
                    .receipt("artifact_close", &format!("stream={}", close.stream));
            }
            other => return Ok(Some(other)),
        }
        Ok(None)
    }

    fn answer(&self, host: &VtableHostServices, invocation: u64, declared: Vec<CborValue>) {
        let status = finish(
            host,
            invocation,
            ActionStatus::Ok,
            Some(map(&[("declared", CborValue::Array(declared))])),
            None,
        );
        self.control.receipt(
            "made",
            &format!("invocation={invocation} status={}", status as u32),
        );
    }
}
